func LookupOperation(id OperationID) (Operation, bool) {
	op, ok := operationTable[id]
	if !ok {
		return Operation{}, false
	}
	op.Roles = append([]Role(nil), op.Roles...)
	codes := map[string]int{}
	for k, v := range op.ErrorCodes {
		codes[k] = v
	}
	op.ErrorCodes = codes
	return op, true
}
